/** Öffentlicher Teaser – für Liste und Exposé ohne NDA */
export function projektOeffentlich(p) {
  if (!p) return null;
  const o = {};
  for (const k of OEFFENTLICH) if (p[k] !== undefined) o[k] = p[k];
  o.highlights = Array.isArray(p.highlights) ? p.highlights : [];
  return o;
}

