302	/** Übergang anwenden (nach erfolgreicher Prüfung) inkl. Nebenwirkungen und Nachricht */
303	function uebergangAnwenden(db, n, art, o, nach, als, extra = {}, ip = "") {
304	  const von = o.status;
305	  const kommentar = v.mehrzeilig(extra.grund || extra.kommentar || "", 1000);
306	
307	  // Nebenwirkungen vor dem Wechsel (Validierung)
308	  if (extra.grund) o.ablehnGrund = kommentar;
309	  if (art === "flaeche" && nach === "pachtangebot") {
310	    const pa = extra.pachtangebot || {};
311	    const euro = v.zahl(pa.euroProHaJahr, { min: 50, max: 50000 });
312	    const jahre = v.zahl(pa.laufzeitJahre, { min: 1, max: 60 });
313	    v.pflicht(euro !== null && jahre !== null, "Pachtangebot: Pacht je ha und Laufzeit angeben.");
314	    o.pachtangebot = { euroProHaJahr: euro, laufzeitJahre: jahre, verlaengerung: v.text(pa.verlaengerung, 80), text: v.mehrzeilig(pa.text, 2000), am: jetzt() };
315	  }
316	  if (art === "projekt" && nach === "veroeffentlicht") {
317	    let satz = v.zahl(extra.provisionSatz, { min: 0, max: 100 });
318	    if (satz !== null && satz > 0.2) satz = satz / 100; // Eingabe in Prozent
319	    v.pflicht(satz !== null && satz >= PROVISION.verkaeufer.min - 1e-9 && satz <= PROVISION.verkaeufer.max + 1e-9, `Provisionssatz muss zwischen ${PROVISION.verkaeufer.min * 100} und ${PROVISION.verkaeufer.max * 100} % liegen.`);
320	    o.provisionSatz = Math.round(satz * 10000) / 10000;
321	    if (!o.veroeffentlichtAm) o.veroeffentlichtAm = jetzt();
322	  }
323	  if (art === "interesse" && nach === "loi_abgegeben") {
324	    const l = extra.loi || {};
325	    const t = v.mehrzeilig(l.text, 3000);
326	    v.pflicht(t.length >= 10, "Bitte beschreiben Sie Ihre Absichtserklärung (mind. 10 Zeichen).");
327	    o.loi = { betrag: v.zahl(l.betrag, { min: 0, max: 1e10 }), text: t, bedingungen: v.mehrzeilig(l.bedingungen, 2000), gueltigBis: v.text(l.gueltigBis, 10), am: jetzt() };
328	  }
329	  let provision = null;
330	  if (art === "projekt" && nach === "verkauft") {
331	    const kaeufer = objekt(db, "interesse", v.kennung(extra.interesseId));
332	    v.pflicht(kaeufer && kaeufer.projektId === o.id && ["nda_freigegeben", "loi_abgegeben", "loi_angenommen"].includes(kaeufer.status), "Käufer muss ein Interessent mit freigegebenem Datenraum sein.");
333	    const kaufpreis = v.zahl(extra.kaufpreis, { min: 1, max: 1e11 });
334	    v.pflicht(kaufpreis, "Bitte Kaufpreis angeben.");
335	    const satz = o.provisionSatz ?? PROVISION.verkaeufer.min;
336	    provision = {
337	      id: neueId("PV"),
338	      projektId: o.id,
339	      anbieterId: o.anbieterId,
340	      investorId: kaeufer.investorId,
341	      interesseId: kaeufer.id,
342	      kaufpreis,
343	      satz,
344	      betrag: Math.round(kaufpreis * satz),
345	      status: "offen",
346	      statusVerlauf: [verlaufEintrag("offen", null, "system", "Automatisch bei Verkauf berechnet.")],
347	      erstelltAm: jetzt(),
348	    };
349	    db.provisionen.push(provision);
350	    // Käufer → abgeschlossen, alle anderen offenen Interessen → abgelehnt
351	    for (const i of db.interessen.filter((x) => x.projektId === o.id)) {
352	      if (i.id === kaeufer.id) systemWechsel(db, "interesse", i, "abgeschlossen", "Kauf abgeschlossen.");
353	      else if (!["abgelehnt", "abgeschlossen"].includes(i.status)) systemWechsel(db, "interesse", i, "abgelehnt", "Projekt anderweitig verkauft.");
354	    }
355	  }
356	
357	  o.status = nach;
358	  o.statusVerlauf = o.statusVerlauf || [];
359	  o.statusVerlauf.push(verlaufEintrag(nach, n, als, kommentar));
360	  o.geaendertAm = jetzt();
361	
362	  // Neu veröffentlicht → Investoren mit passendem Suchprofil benachrichtigen
363	  if (art === "projekt" && nach === "veroeffentlicht") {
364	    suchprofilAlarm(db, o);
365	  }
366	
367	  // LOI angenommen → Projekt reserviert
368	  if (art === "interesse" && nach === "loi_angenommen") {
369	    const p = objekt(db, "projekt", o.projektId);
370	    if (p && p.status === "veroeffentlicht") systemWechsel(db, "projekt", p, "reserviert", "LOI eines Investors angenommen.");
371	  }
372	
373	  if (art !== "provision") {
374	    const text = `Status: „${statusLabel(art, von)}“ → „${statusLabel(art, nach)}“.${kommentar ? ` ${kommentar}` : ""}`;
375	    const eigen = als === "eigentuemer";
376	    nachricht(db, { bezugArt: art, bezugId: o.id, vonId: n?.id, vonAdmin: als === "admin", system: true, text, ...(eigen ? { gelesenNutzer: true, gelesenAdmin: false } : {}) });
377	  }
378	  if (provision) {
379	    protokoll(db, n, "provision", "provision", provision.id, `Provision ${provision.betrag} € (${provision.satz * 100} %) für ${o.id}`, ip);
380	  }
381	  protokoll(db, n, "status", art, o.id, `${statusLabel(art, von)} → ${statusLabel(art, nach)}`, ip);
382	}
