462	export async function nachrichtenThreads(n, { nurUngelesen = false } = {}) {
463	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
464	  const db = await lesen();
465	  const admin = istAdmin(n);
466	  const gruppen = new Map();
467	  for (const m of db.nachrichten) {
468	    const key = `${m.bezugArt}:${m.bezugId}`;
469	    if (!gruppen.has(key)) gruppen.set(key, []);
470	    gruppen.get(key).push(m);
471	  }
472	  const threads = [];
473	  for (const [key, liste] of gruppen) {
474	    const [art, id] = key.split(":");
475	    const o = bezugObjekt(db, art, id);
476	    if (!o) continue;
477	    const eigen = besitzer(db, art, o) === n.id;
478	    if (!admin && !eigen) continue;
479	    const info = threadInfo(db, art, id, n);
480	    const sortiert = liste.sort((a, b) => a.am.localeCompare(b.am));
481	    const letzte = sortiert[sortiert.length - 1];
482	    const ungelesen = sortiert.filter((m) => (admin && !eigen ? !m.gelesenAdmin : !m.gelesenNutzer)).length;
483	    if (nurUngelesen && !ungelesen) continue;
484	    threads.push({ bezugArt: art, bezugId: id, ...info, anzahl: sortiert.length, ungelesen, letzte: { text: letzte.text.slice(0, 160), am: letzte.am, vonAdmin: letzte.vonAdmin, system: letzte.system } });
485	  }
486	  return threads.sort((a, b) => b.letzte.am.localeCompare(a.letzte.am));
487	}
