489	export async function nachrichten(n, bezugArt, bezugId, { markieren = true } = {}) {
490	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
491	  const db = await lesen();
492	  const o = darfBezug(db, n, bezugArt, bezugId);
493	  const eigen = besitzer(db, bezugArt, o) === n.id;
494	  const alsAdmin = istAdmin(n) && !eigen;
495	  const liste = db.nachrichten.filter((m) => m.bezugArt === bezugArt && m.bezugId === bezugId).sort((a, b) => a.am.localeCompare(b.am));
496	  const offen = liste.filter((m) => (alsAdmin ? !m.gelesenAdmin : !m.gelesenNutzer));
497	  const hinweise = (db.benachrichtigungen || []).filter((b) => b.nutzerId === n.id && !b.gelesen && b.objektArt === bezugArt && b.objektId === bezugId && ["status", "nachricht", "nda"].includes(b.art));
498	  if (markieren && (offen.length || hinweise.length)) {
499	    await aendern((d) => {
500	      const ids = new Set(offen.map((m) => m.id));
501	      for (const m of d.nachrichten) if (ids.has(m.id)) m[alsAdmin ? "gelesenAdmin" : "gelesenNutzer"] = true;
502	      const bIds = new Set(hinweise.map((b) => b.id));
503	      for (const b of d.benachrichtigungen || []) if (bIds.has(b.id)) b.gelesen = true;
504	    });
505	  }
506	  return {
507	    ...threadInfo(db, bezugArt, bezugId, n),
508	    bezugArt,
509	    bezugId,
510	    nachrichten: liste.map((m) => ({
511	      id: m.id,
512	      text: m.text,
513	      am: m.am,
514	      system: m.system,
515	      vonAdmin: m.vonAdmin,
516	      eigene: m.vonId === n.id && !m.system,
517	      vonName: m.vonAdmin ? "ÖkoInvest Backoffice" : nameVon(db, m.vonId) || "Nutzer",
518	      neu: alsAdmin ? !m.gelesenAdmin : !m.gelesenNutzer,
519	    })),
520	  };
521	}
