              <Angaben items={Object.entries(VERTRAULICH_FELDER).map(([k, label]) => ({ label, wert: p.vertraulich?.[k] === undefined || p.vertraulich?.[k] === null ? "" : String(p.vertraulich[k]), breit: k === "details" }))} />
