  bieterStarten: "bieter.starten",
  bieterAktion: "bieter.aktion",
  gebotAbgeben: "bieter.gebot_abgeben",
  gebotZurueckziehen: "bieter.gebot_zurueckziehen",
  datenraum: "dealroom.datenraum",
